 ('Terziköy Kaplıcaları','Termal','Termal turizm alanı','Aydınca, Amasya',40.5000::float8,35.6500::float8,'terzikoy-kaplicalari','Amasya çevresinde bilinen termal turizm noktası.','Termal tesisler ve hizmetler mevsime göre değişebileceğinden ziyaret öncesi açık olma ve kullanım koşulları kontrol edilmelidir.','https://oka.gov.tr/assets/upload/dosyalar/amasyada-yatirim-rehberitr.pdf','["termal","dinlenme","sağlık turizmi"]'),
 ('Yassıçal Sunağı','Tarih','Antik sunak','Yassıçal, Amasya',40.5500::float8,35.8000::float8,'yassical-sunagi','Helenistik-Roma dönemlerinde törenlerde kullanılmış antik kutsal alan.','Günümüzde kalıntıları sınırlı olsa da Amasya’nın antik dönem arkeoloji rotasında yer alır.','https://www.amasya.gov.tr/oren-yerleri','["arkeoloji","antik dönem","tarih"]')
) as v(name,category,place_type,address,lat,lon,slug,short_description,long_description,source_url,tags)
where not exists (
 select 1 from public.places p
 where lower(trim(p.city))='amasya'
   and (lower(trim(p.name))=lower(trim(v.name)) or p.slug=trim(v.slug))
);